def migrate_legacy_destinations(apps, schema_editor):
    """Preserve configured destinations without touching historical send results."""

    Rule = apps.get_model("lens", "AlertRule")
    Subscription = apps.get_model("lens", "AlertSubscription")
    alias = schema_editor.connection.alias
    for rule in Rule.objects.using(alias).exclude(channel_uuid=None).iterator():
        Subscription.objects.using(alias).create(
            rule_id=rule.pk,
            name="Legacy destination",
            channel_uuid=rule.channel_uuid,
            email_recipients=rule.email_recipients,
        )


def migrate_legacy_events(apps, schema_editor):
    """Backfill deduplication keys without replaying historical notifications."""

    Event = apps.get_model("lens", "AlertEvent")
    alias = schema_editor.connection.alias
    seen = set()
    for event in Event.objects.using(alias).select_related("run", "rule").order_by("pk").iterator():
        source_uuid = str(event.run.uuid) if event.run_id else ""
        key = f"run:{source_uuid}:terminal" if source_uuid else f"legacy:{event.uuid}"
        identity = (event.rule_id, key)
        if identity in seen:
            key = f"{key}:legacy:{event.uuid}"
        seen.add(identity)
        Event.objects.using(alias).filter(pk=event.pk).update(
            source_key=key,
            source_uuid=source_uuid,
            rule_snapshot={"name": event.rule.name, "events": event.rule.events} if event.rule_id else {},
        )


